/** @jsxImportSource preact */
import { useEffect, useRef } from "preact/hooks";
import { mountRecentPurchaseToast, type RecentPurchaseToastOptions } from "../../components/recent-purchase-toast/RecentPurchaseToastEngine.js";
import type { MotionController } from "../../components/recent-purchase-toast/motion-runtime";

export function RecentPurchaseToast({ options, className }: { options?: RecentPurchaseToastOptions; className?: string }) {
  const host = useRef<HTMLDivElement>(null);
  const controller = useRef<MotionController | null>(null);
  useEffect(() => {
    const instance = mountRecentPurchaseToast(host.current!, options);
    controller.current = instance;
    return () => { instance.destroy(); controller.current = null; };
    // Options are updated below without remounting the state machine.
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEffect(() => { controller.current?.update(options ?? {}); }, [options]);
  return <div ref={host} className={className} data-motion-component="recent-purchase-toast" />;
}

